-- LOT 02 - Conteneurs ID 31 a 34
-- Intermediaire: ne pas importer seul; sera assemble dans le SQL final.

START TRANSACTION;

UPDATE `conteneurs`
SET
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Rental container No. 108. We rent containers in several sizes, including 20DC, 40HC and 45HCPW, with a wide choice of units and colours available on site. The most popular rental unit is the 6 m (20DC) container, whose size and weight make it possible to handle and lift it by crane where the customer needs it.\n\nUse it to store furniture, building materials, seasonal equipment or other items. It is dust-tight and robust, providing useful extra storage. Containers can also be customised for advertising: we can apply graphics or paint them in your colours and deliver them to the chosen location.\n\nTransport can be arranged using a crane truck or sideloader; a RAM backloader is used for difficult access. Best-price guarantee for the container.\n\nTECHNICAL FEATURES\n- Length: 6 m\n- Colour: yellow\n- Forklift pockets\n- Lockable\n- Price: EUR 300 + VAT'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Conteneur de location n° 108. Nous louons des conteneurs de plusieurs dimensions, notamment 20DC, 40HC et 45HCPW. Un large choix de conteneurs et de couleurs est disponible sur place. Le modèle de location le plus demandé est le 20DC de 6 m ; ses dimensions et son poids permettent de le déplacer et de le lever par grue à l’endroit choisi par le client.\n\nIl peut servir au stockage de meubles, de matériaux de construction, d’équipements saisonniers ou d’autres biens. Étanche à la poussière et robuste, il offre un espace de stockage supplémentaire. Les conteneurs peuvent également être personnalisés à des fins publicitaires : nous pouvons y appliquer un visuel ou les peindre dans vos couleurs, puis les transporter sur place.\n\nLe transport peut être organisé par camion-grue ou sideloader ; le RAM backloader est utilisé pour les accès difficiles. Garantie du meilleur prix pour le conteneur.\n\nCARACTÉRISTIQUES TECHNIQUES\n- Longueur : 6 m\n- Couleur : jaune\n- Passages pour chariot élévateur\n- Verrouillable\n- Prix : 300 € + TVA'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Contenedor de alquiler n.º 108. Alquilamos contenedores de distintos tamaños, incluidos 20DC, 40HC y 45HCPW. Disponemos de una amplia selección de contenedores y colores en nuestras instalaciones. El modelo de alquiler más solicitado es el 20DC de 6 m; sus dimensiones y peso permiten manipularlo y elevarlo con grúa en el lugar que necesite el cliente.\n\nPuede utilizarse para guardar muebles, materiales de construcción, equipos de temporada u otros artículos. Es hermético al polvo y robusto, y ofrece espacio de almacenamiento adicional. También se puede personalizar con fines publicitarios: podemos aplicar gráficos o pintarlo con sus colores y transportarlo al lugar indicado.\n\nEl transporte puede organizarse con camión grúa o sideloader; para accesos difíciles se utiliza un RAM backloader. Garantía del mejor precio para el contenedor.\n\nCARACTERÍSTICAS TÉCNICAS\n- Longitud: 6 m\n- Color: amarillo\n- Bolsillos para carretilla elevadora\n- Se puede cerrar con llave\n- Precio: 300 € + IVA'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Mietcontainer Nr. 108. Wir vermieten Container in verschiedenen Grössen, darunter 20DC, 40HC und 45HCPW. Eine grosse Auswahl an Containern und Farben ist vor Ort verfügbar. Der beliebteste Mietcontainer ist der 6-m-Container (20DC). Aufgrund seiner Abmessungen und seines Gewichts kann er mit einem Kran an den vom Kunden gewünschten Standort gebracht werden.\n\nEr eignet sich zur Lagerung von Möbeln, Baumaterialien, saisonaler Ausrüstung und anderen Gegenständen. Der Container ist staubdicht und robust und bietet zusätzlichen Stauraum. Er kann auch für Werbung gestaltet werden: Wir bringen Folien oder Grafiken an oder lackieren ihn in Ihren Farben und transportieren ihn zum gewünschten Standort.\n\nDer Transport kann mit Kran-Lkw oder Sideloader organisiert werden; für schwierige Zufahrten kommt ein RAM-Backloader zum Einsatz. Bestpreisgarantie für den Container.\n\nTECHNISCHE MERKMALE\n- Länge: 6 m\n- Farbe: Gelb\n- Staplertaschen\n- Abschliessbar\n- Preis: 300 € zzgl. MwSt.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Huurcontainer nr. 108. We verhuren containers in verschillende maten, waaronder 20DC, 40HC en 45HCPW. Op locatie is een ruime keuze aan containers en kleuren beschikbaar. De populairste huurcontainer is de 6 m (20DC); dankzij de afmetingen en het gewicht kan deze met een kraan worden verplaatst naar de gewenste plek van de klant.\n\nDe container is geschikt voor meubels, bouwmaterialen, seizoensapparatuur en andere goederen. Hij is stofdicht en stevig en biedt extra opslagruimte. Containers kunnen ook voor reclame worden aangepast: we kunnen afbeeldingen aanbrengen of de container in uw kleuren schilderen en naar de gewenste locatie vervoeren.\n\nVervoer kan worden geregeld met een kraanwagen of sideloader; voor moeilijke toegangen wordt een RAM-backloader gebruikt. Laagsteprijsgarantie voor de container.\n\nTECHNISCHE KENMERKEN\n- Lengte: 6 m\n- Kleur: geel\n- Heftruckkokers\n- Afsluitbaar\n- Prijs: € 300 + btw'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Vuokrakontti nro 108. Vuokraamme erikokoisia kontteja, kuten 20DC-, 40HC- ja 45HCPW-malleja. Terminaalissa on laaja valikoima kontteja ja värejä. Suosituin vuokramalli on 6 metrin 20DC-kontti. Sen koon ja painon ansiosta se voidaan siirtää ja nostaa nosturilla asiakkaan haluamaan paikkaan.\n\nKontti soveltuu huonekalujen, rakennusmateriaalien, kausilaitteiden ja muiden tavaroiden varastointiin. Se on pölytiivis ja kestävä ja tarjoaa lisää säilytystilaa. Kontteja voidaan myös käyttää mainontaan: voimme kiinnittää niihin grafiikkaa tai maalata ne yrityksenne väreihin ja kuljettaa ne kohteeseen.\n\nKuljetus voidaan järjestää nosturiautolla tai sivulastaajalla; vaikeapääsyisiin kohteisiin käytetään RAM-backloaderia. Kontille parhaan hinnan takuu.\n\nTEKNISET TIEDOT\n- Pituus: 6 m\n- Väri: keltainen\n- Trukkitaskut\n- Lukittava\n- Hinta: 300 € + alv'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Mietcontainer Nr. 108. Wir vermieten Container in verschiedenen Grössen, darunter 20DC, 40HC und 45HCPW. Eine grosse Auswahl an Containern und Farben ist vor Ort verfügbar. Der beliebteste Mietcontainer ist der 6-m-Container (20DC). Aufgrund seiner Abmessungen und seines Gewichts kann er mit einem Kran an den vom Kunden gewünschten Standort gebracht werden.\n\nEr eignet sich zur Lagerung von Möbeln, Baumaterialien, saisonaler Ausrüstung und anderen Gegenständen. Der Container ist staubdicht und robust und bietet zusätzlichen Stauraum. Er kann auch für Werbung gestaltet werden: Wir bringen Folien oder Grafiken an oder lackieren ihn in Ihren Farben und transportieren ihn zum gewünschten Standort.\n\nDer Transport kann mit Kran-Lkw oder Sideloader organisiert werden; für schwierige Zufahrten kommt ein RAM-Backloader zum Einsatz. Bestpreisgarantie für den Container.\n\nTECHNISCHE MERKMALE\n- Länge: 6 m\n- Farbe: Gelb\n- Staplertaschen\n- Abschliessbar\n- Preis: 300 € zzgl. MwSt.')
WHERE `id` = 31 AND `reference` = 'Rental Container nr 108';

UPDATE `conteneurs`
SET
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Containex 3D portable office cabin, model 0088. A high-quality, CE-certified portable cabin with a bolted frame, described as more resistant than a welded frame. Suitable as an office, summer house, commercial space or sales outlet.\n\nTECHNICAL FEATURES\n- External colour: light grey RAL 7035; special colours available\n- Insulation: walls with 45-60 mm PU foam; roof with 100 mm mineral wool; floor with 100 mm mineral wool or 60 mm PU panels\n- Roof covering: coated or painted sheet metal\n- One front door: 875 mm wide, 811 mm clear opening, 2,065 mm high\n- One standard window; custom positioning available\n- Two lights, one electrical panel, two sockets and one switch\n\nOPTIONS\n- Custom window and door placement (up to 1 week)\n- Panoramic windows (up to 4 weeks)\n- Internal wood lining; different window, door and light types; variable heights; extra sockets on request\n\nINSTALLATION AND DELIVERY\n- Installation in under 30 minutes; no foundation required\n- Standard models may be delivered the same day\n- Installation arranged to suit the customer\n\nIMPORTANT: this listing concerns a 3D model and cabin structure, not the structure alone. The portable cabins sold are supplied complete.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Cabine de bureau portable Containex 3D, modèle 0088. Cabine de qualité certifiée CE, avec une structure boulonnée présentée comme plus résistante qu’une structure soudée. Convient comme bureau, résidence d’été, espace commercial ou point de vente.\n\nCARACTÉRISTIQUES TECHNIQUES\n- Couleur extérieure : gris clair RAL 7035 ; coloris spéciaux disponibles\n- Isolation : murs en mousse PU de 45 à 60 mm ; toit en laine minérale de 100 mm ; sol en laine minérale de 100 mm ou panneaux PU de 60 mm\n- Couverture : tôle étamée ou peinte\n- Une porte avant : largeur 875 mm, passage 811 mm, hauteur 2 065 mm\n- Une fenêtre standard ; positionnement personnalisé possible\n- Deux luminaires, un tableau électrique, deux prises et un interrupteur\n\nOPTIONS\n- Positionnement personnalisé des fenêtres et portes (jusqu’à une semaine)\n- Fenêtres panoramiques (jusqu’à quatre semaines)\n- Habillage intérieur en bois ; différents types de fenêtres, portes et luminaires ; hauteur variable ; prises supplémentaires sur demande\n\nINSTALLATION ET LIVRAISON\n- Installation en moins de 30 minutes ; aucune fondation nécessaire\n- Livraison le jour même possible pour les modèles standard\n- Installation adaptée aux besoins du client\n\nIMPORTANT : cette fiche concerne un modèle 3D et une structure de cabine, et non la vente de la structure seule. Les cabines portables vendues sont fournies complètes.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Cabina de oficina portátil Containex 3D, modelo 0088. Cabina de alta calidad con certificación CE y estructura atornillada, descrita como más resistente que una estructura soldada. Adecuada como oficina, casa de verano, espacio comercial o punto de venta.\n\nCARACTERÍSTICAS TÉCNICAS\n- Color exterior: gris claro RAL 7035; hay colores especiales disponibles\n- Aislamiento: paredes con espuma PU de 45-60 mm; techo con lana mineral de 100 mm; suelo con lana mineral de 100 mm o paneles PU de 60 mm\n- Cubierta: chapa estañada o pintada\n- Una puerta frontal: 875 mm de ancho, paso de 811 mm y 2.065 mm de alto\n- Una ventana estándar; posición personalizable\n- Dos lámparas, un cuadro eléctrico, dos enchufes y un interruptor\n\nOPCIONES\n- Posición personalizada de puertas y ventanas (hasta 1 semana)\n- Ventanas panorámicas (hasta 4 semanas)\n- Revestimiento interior de madera; varios tipos de ventanas, puertas y lámparas; alturas variables; enchufes adicionales bajo pedido\n\nINSTALACIÓN Y ENTREGA\n- Instalación en menos de 30 minutos; no requiere cimientos\n- Posible entrega en el mismo día para modelos estándar\n- Instalación adaptada a las necesidades del cliente\n\nIMPORTANTE: el anuncio corresponde a un modelo 3D y a la estructura de una cabina, no a la venta de la estructura por separado. Las cabinas portátiles vendidas se suministran completas.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Containex 3D-Bürokabine, Modell 0088. Hochwertige, CE-zertifizierte mobile Kabine mit verschraubtem Rahmen, der laut Beschreibung widerstandsfähiger als ein geschweisster Rahmen ist. Geeignet als Büro, Sommerhaus, Gewerbefläche oder Verkaufsstelle.\n\nTECHNISCHE MERKMALE\n- Aussenfarbe: Hellgrau RAL 7035; Sonderfarben erhältlich\n- Isolierung: Wände mit 45-60 mm PU-Schaum; Dach mit 100 mm Mineralwolle; Boden mit 100 mm Mineralwolle oder 60-mm-PU-Platten\n- Dachabdeckung: verzinktes oder lackiertes Blech\n- Eine Eingangstür: 875 mm breit, Durchgang 811 mm, Höhe 2.065 mm\n- Ein Standardfenster; individuelle Position möglich\n- Zwei Leuchten, ein Elektrokasten, zwei Steckdosen und ein Schalter\n\nOPTIONEN\n- Individuelle Position von Fenstern und Türen (bis zu 1 Woche)\n- Panoramafenster (bis zu 4 Wochen)\n- Innenverkleidung aus Holz; verschiedene Fenster-, Tür- und Leuchtentypen; variable Höhen; zusätzliche Steckdosen auf Anfrage\n\nMONTAGE UND LIEFERUNG\n- Montage in weniger als 30 Minuten; kein Fundament erforderlich\n- Lieferung am selben Tag bei Standardmodellen möglich\n- Montage nach Kundenwunsch\n\nWICHTIG: Das Angebot betrifft ein 3D-Modell und die Kabinenstruktur, nicht den Verkauf der Struktur allein. Die verkauften mobilen Kabinen werden vollständig geliefert.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Containex 3D mobiele kantoorunit, model 0088. Een hoogwaardige, CE-gecertificeerde unit met een geschroefd frame, dat volgens de beschrijving sterker is dan een gelast frame. Geschikt als kantoor, zomerhuis, bedrijfsruimte of verkooppunt.\n\nTECHNISCHE KENMERKEN\n- Buitenkleur: lichtgrijs RAL 7035; speciale kleuren beschikbaar\n- Isolatie: wanden met 45-60 mm PU-schuim; dak met 100 mm minerale wol; vloer met 100 mm minerale wol of PU-panelen van 60 mm\n- Dakbedekking: vertind of geschilderd plaatstaal\n- Eén voordeur: 875 mm breed, doorgang 811 mm, hoogte 2.065 mm\n- Eén standaardraam; plaatsing op maat mogelijk\n- Twee lampen, één elektriciteitskast, twee stopcontacten en één schakelaar\n\nOPTIES\n- Aangepaste plaatsing van ramen en deuren (maximaal 1 week)\n- Panoramische ramen (maximaal 4 weken)\n- Houten binnenbekleding; verschillende soorten ramen, deuren en lampen; variabele hoogtes; extra stopcontacten op aanvraag\n\nINSTALLATIE EN LEVERING\n- Installatie in minder dan 30 minuten; geen fundering nodig\n- Levering op dezelfde dag mogelijk voor standaardmodellen\n- Installatie afgestemd op de wensen van de klant\n\nBELANGRIJK: deze aanbieding betreft een 3D-model en de structuur van een unit, niet de verkoop van alleen de structuur. De verkochte mobiele units worden compleet geleverd.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Containex 3D -siirrettävä toimistomoduuli, malli 0088. Laadukas, CE-sertifioitu moduuli, jossa on pultattu runko; kuvauksen mukaan se kestää paremmin kuin hitsattu runko. Sopii toimistoksi, kesämökiksi, liiketilaksi tai myyntipisteeksi.\n\nTEKNISET TIEDOT\n- Ulkoväri: vaaleanharmaa RAL 7035; erikoisvärejä saatavilla\n- Eristys: seinissä 45-60 mm PU-vaahtoa; katossa 100 mm mineraalivillaa; lattiassa 100 mm mineraalivillaa tai 60 mm PU-paneelit\n- Kattopelti: tinattu tai maalattu\n- Yksi etuovi: leveys 875 mm, vapaa aukko 811 mm, korkeus 2 065 mm\n- Yksi vakioikkuna; sijoitus voidaan räätälöidä\n- Kaksi valaisinta, yksi sähkökeskus, kaksi pistorasiaa ja yksi katkaisin\n\nLISÄVARUSTEET\n- Ikkunoiden ja ovien räätälöity sijoittelu (enintään 1 viikko)\n- Panoraamaikkunat (enintään 4 viikkoa)\n- Puinen sisäverhous; erilaisia ikkuna-, ovi- ja valaisinmalleja; vaihtelevat korkeudet; lisäpistorasioita pyynnöstä\n\nASENNUS JA TOIMITUS\n- Asennus alle 30 minuutissa; perustusta ei tarvita\n- Vakiomallit voidaan mahdollisesti toimittaa samana päivänä\n- Asennus asiakkaan tarpeiden mukaan\n\nTÄRKEÄÄ: ilmoitus koskee 3D-mallia ja moduulin runkoa, ei pelkän rungon myyntiä. Myytävät siirrettävät moduulit toimitetaan kokonaisina.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Containex 3D-Bürokabine, Modell 0088. Hochwertige, CE-zertifizierte mobile Kabine mit verschraubtem Rahmen, der laut Beschreibung widerstandsfähiger als ein geschweisster Rahmen ist. Geeignet als Büro, Sommerhaus, Gewerbefläche oder Verkaufsstelle.\n\nTECHNISCHE MERKMALE\n- Aussenfarbe: Hellgrau RAL 7035; Sonderfarben erhältlich\n- Isolierung: Wände mit 45-60 mm PU-Schaum; Dach mit 100 mm Mineralwolle; Boden mit 100 mm Mineralwolle oder 60-mm-PU-Platten\n- Dachabdeckung: verzinktes oder lackiertes Blech\n- Eine Eingangstür: 875 mm breit, Durchgang 811 mm, Höhe 2.065 mm\n- Ein Standardfenster; individuelle Position möglich\n- Zwei Leuchten, ein Elektrokasten, zwei Steckdosen und ein Schalter\n\nOPTIONEN\n- Individuelle Position von Fenstern und Türen (bis zu 1 Woche)\n- Panoramafenster (bis zu 4 Wochen)\n- Innenverkleidung aus Holz; verschiedene Fenster-, Tür- und Leuchtentypen; variable Höhen; zusätzliche Steckdosen auf Anfrage\n\nMONTAGE UND LIEFERUNG\n- Montage in weniger als 30 Minuten; kein Fundament erforderlich\n- Lieferung am selben Tag bei Standardmodellen möglich\n- Montage nach Kundenwunsch\n\nWICHTIG: Das Angebot betrifft ein 3D-Modell und die Kabinenstruktur, nicht den Verkauf der Struktur allein. Die verkauften mobilen Kabinen werden vollständig geliefert.')
WHERE `id` = 32 AND `reference` = 'Office Cabin Containex 3D – 0088';

UPDATE `conteneurs`
SET
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Containex Basic Anthracite office cabin, 6.00 m long, 2.44 m wide and 2.60 m high.\n\nTECHNICAL FEATURES\n- External dimensions: 6.00 x 2.44 x 2.59 m; internal dimensions: 5.85 x 2.30 x 2.34 m\n- Floor load capacity: 200 kg/m2, with an increase available\n- Anthracite grey RAL 7016 frame and panels; DC Standard type (double container)\n- Insulation: 45 mm PU foam walls; 100 mm mineral wool roof; 60 mm PU floor panels\n- Standard equipment: one opening window, one outward-opening entrance door, two sockets, one light switch, one electrical panel, two lights and CE-marked heating\n- Electrical connection: 230 V / 32 A / 3-pole\n- Door: 875 mm wide; opening 811 mm; opening height 2,065 mm. Window sill height: 870 mm\n- Bolted frame; galvanised or painted sheet-metal roof\n- Installation in under 30 minutes; no foundation required\n\nUSES\nTemporary or permanent office, seasonal cottage, sales outlet, commercial space or mini-home.\n\nSERVICES\nSale: EUR 4,890 + VAT; short- or long-term rental; installation included.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Cabine de bureau Containex Basic Anthracite, longue de 6,00 m, large de 2,44 m et haute de 2,60 m.\n\nCARACTÉRISTIQUES TECHNIQUES\n- Dimensions extérieures : 6,00 x 2,44 x 2,59 m ; dimensions intérieures : 5,85 x 2,30 x 2,34 m\n- Charge admissible au sol : 200 kg/m², valeur pouvant être augmentée\n- Châssis et panneaux gris anthracite RAL 7016 ; type DC Standard (conteneur double)\n- Isolation : murs en mousse PU de 45 mm ; toit en laine minérale de 100 mm ; plancher en panneaux PU de 60 mm\n- Équipement standard : une fenêtre ouvrante, une porte d’entrée ouvrant vers l’extérieur, deux prises, un interrupteur, un tableau électrique, deux luminaires et un chauffage certifié CE\n- Raccordement électrique : 230 V / 32 A / 3 pôles\n- Porte : largeur 875 mm, passage 811 mm, hauteur de passage 2 065 mm. Hauteur de la fenêtre depuis le sol : 870 mm\n- Châssis boulonné ; toit en tôle galvanisée ou peinte\n- Installation en moins de 30 minutes ; aucune fondation nécessaire\n\nUTILISATIONS\nBureau temporaire ou permanent, chalet saisonnier, point de vente, espace commercial ou mini-maison.\n\nSERVICES\nVente : 4 890 € + TVA ; location courte ou longue durée ; installation incluse.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Cabina de oficina Containex Basic Anthracite, de 6,00 m de largo, 2,44 m de ancho y 2,60 m de alto.\n\nCARACTERÍSTICAS TÉCNICAS\n- Dimensiones exteriores: 6,00 x 2,44 x 2,59 m; interiores: 5,85 x 2,30 x 2,34 m\n- Capacidad de carga del suelo: 200 kg/m², ampliable\n- Estructura y paneles en gris antracita RAL 7016; tipo DC Standard (contenedor doble)\n- Aislamiento: paredes con espuma PU de 45 mm; techo con lana mineral de 100 mm; suelo con paneles PU de 60 mm\n- Equipamiento estándar: una ventana practicable, una puerta de entrada que abre hacia fuera, dos enchufes, un interruptor, un cuadro eléctrico, dos lámparas y calefacción con marcado CE\n- Conexión eléctrica: 230 V / 32 A / 3 polos\n- Puerta: 875 mm de ancho; paso de 811 mm y altura de paso de 2.065 mm. Altura de la ventana desde el suelo: 870 mm\n- Estructura atornillada; techo de chapa galvanizada o pintada\n- Instalación en menos de 30 minutos; no requiere cimientos\n\nUSOS\nOficina temporal o permanente, casa de temporada, punto de venta, espacio comercial o minicasa.\n\nSERVICIOS\nVenta: 4.890 € + IVA; alquiler a corto o largo plazo; instalación incluida.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Containex-Bürokabine Basic Anthracite, 6,00 m lang, 2,44 m breit und 2,60 m hoch.\n\nTECHNISCHE MERKMALE\n- Aussenmasse: 6,00 x 2,44 x 2,59 m; Innenmasse: 5,85 x 2,30 x 2,34 m\n- Bodenbelastbarkeit: 200 kg/m², Erhöhung möglich\n- Rahmen und Paneele in Anthrazitgrau RAL 7016; Typ DC Standard (Doppelcontainer)\n- Isolierung: Wände mit 45 mm PU-Schaum; Dach mit 100 mm Mineralwolle; Boden mit 60-mm-PU-Platten\n- Standardausstattung: ein zu öffnendes Fenster, eine nach aussen öffnende Eingangstür, zwei Steckdosen, ein Lichtschalter, ein Elektrokasten, zwei Leuchten und CE-gekennzeichnete Heizung\n- Stromanschluss: 230 V / 32 A / 3-polig\n- Tür: 875 mm breit; Durchgang 811 mm; Durchgangshöhe 2.065 mm. Fensterunterkante 870 mm über dem Boden\n- Verschraubter Rahmen; Dach aus verzinktem oder lackiertem Blech\n- Montage in weniger als 30 Minuten; kein Fundament erforderlich\n\nEINSATZBEREICHE\nTemporäres oder dauerhaftes Büro, saisonales Ferienhaus, Verkaufsstelle, Gewerbefläche oder Minihaus.\n\nLEISTUNGEN\nKaufpreis: 4.890 € zzgl. MwSt.; Kurz- oder Langzeitmiete; Montage inbegriffen.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Containex Basic Anthracite-kantoorunit, 6,00 m lang, 2,44 m breed en 2,60 m hoog.\n\nTECHNISCHE KENMERKEN\n- Buitenafmetingen: 6,00 x 2,44 x 2,59 m; binnenafmetingen: 5,85 x 2,30 x 2,34 m\n- Draagvermogen van de vloer: 200 kg/m², verhoging mogelijk\n- Frame en panelen in antracietgrijs RAL 7016; type DC Standard (dubbele container)\n- Isolatie: wanden met 45 mm PU-schuim; dak met 100 mm minerale wol; vloer met PU-panelen van 60 mm\n- Standaarduitrusting: één te openen raam, één naar buiten draaiende toegangsdeur, twee stopcontacten, één lichtschakelaar, één elektriciteitskast, twee lampen en CE-gemarkeerde verwarming\n- Elektrische aansluiting: 230 V / 32 A / 3-polig\n- Deur: 875 mm breed; doorgang 811 mm; doorgangshoogte 2.065 mm. Raamhoogte vanaf de vloer: 870 mm\n- Geschroefd frame; dak van verzinkt of geschilderd plaatstaal\n- Installatie in minder dan 30 minuten; geen fundering nodig\n\nTOEPASSINGEN\nTijdelijk of permanent kantoor, seizoenswoning, verkooppunt, bedrijfsruimte of tiny house.\n\nDIENSTEN\nKoopprijs: € 4.890 + btw; korte- of langetermijnverhuur; installatie inbegrepen.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Containex Basic Anthracite -toimistomoduuli, pituus 6,00 m, leveys 2,44 m ja korkeus 2,60 m.\n\nTEKNISET TIEDOT\n- Ulkomitat: 6,00 x 2,44 x 2,59 m; sisämitat: 5,85 x 2,30 x 2,34 m\n- Lattian kantavuus: 200 kg/m², korotettavissa\n- Runko ja paneelit antrasiitinharmaat RAL 7016; tyyppi DC Standard (kaksoiskontti)\n- Eristys: seinissä 45 mm PU-vaahtoa; katossa 100 mm mineraalivillaa; lattiassa 60 mm PU-paneelit\n- Vakiovarustus: yksi avattava ikkuna, ulospäin avautuva ulko-ovi, kaksi pistorasiaa, valokatkaisin, sähkökeskus, kaksi valaisinta ja CE-merkitty lämmitys\n- Sähköliitäntä: 230 V / 32 A / 3-napainen\n- Ovi: leveys 875 mm; vapaa aukko 811 mm ja aukon korkeus 2 065 mm. Ikkunan alareuna 870 mm lattiasta\n- Pultattu runko; katto sinkittyä tai maalattua levyä\n- Asennus alle 30 minuutissa; perustusta ei tarvita\n\nKÄYTTÖKOHTEET\nTilapäinen tai pysyvä toimisto, kausimökki, myyntipiste, liiketila tai minitalo.\n\nPALVELUT\nMyyntihinta: 4 890 € + alv; lyhyt- tai pitkäaikainen vuokraus; asennus sisältyy.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Containex-Bürokabine Basic Anthracite, 6,00 m lang, 2,44 m breit und 2,60 m hoch.\n\nTECHNISCHE MERKMALE\n- Aussenmasse: 6,00 x 2,44 x 2,59 m; Innenmasse: 5,85 x 2,30 x 2,34 m\n- Bodenbelastbarkeit: 200 kg/m², Erhöhung möglich\n- Rahmen und Paneele in Anthrazitgrau RAL 7016; Typ DC Standard (Doppelcontainer)\n- Isolierung: Wände mit 45 mm PU-Schaum; Dach mit 100 mm Mineralwolle; Boden mit 60-mm-PU-Platten\n- Standardausstattung: ein zu öffnendes Fenster, eine nach aussen öffnende Eingangstür, zwei Steckdosen, ein Lichtschalter, ein Elektrokasten, zwei Leuchten und CE-gekennzeichnete Heizung\n- Stromanschluss: 230 V / 32 A / 3-polig\n- Tür: 875 mm breit; Durchgang 811 mm; Durchgangshöhe 2.065 mm. Fensterunterkante 870 mm über dem Boden\n- Verschraubter Rahmen; Dach aus verzinktem oder lackiertem Blech\n- Montage in weniger als 30 Minuten; kein Fundament erforderlich\n\nEINSATZBEREICHE\nTemporäres oder dauerhaftes Büro, saisonales Ferienhaus, Verkaufsstelle, Gewerbefläche oder Minihaus.\n\nLEISTUNGEN\nKaufpreis: 4.890 € zzgl. MwSt.; Kurz- oder Langzeitmiete; Montage inbegriffen.')
WHERE `id` = 33 AND `reference` = 'Office Cabin Containex Basic Anthracite –';

UPDATE `conteneurs`
SET
  `description` = 'Vendita di container marittimo nuovo 40HC, high cube da 40 piedi, riferimento MIIU3049105. I container sono fabbricati in Asia e consegnati al nostro terminal con un trasporto di sola andata, per evitare i costi aggiuntivi di trasporto che altrimenti inciderebbero sul prezzo del container.\n\nCARATTERISTICHE\n- Garanzia di resistenza alle intemperie di 50 anni\n- Le immagini corrispondono al container presentato; possono essere presenti lievi difetti estetici dovuti al trasporto\n- Il container marittimo dispone di quattro punti di chiusura ed è predisposto per piu di tre lucchetti\n- Il container di stoccaggio dispone di tre punti di chiusura rialzati rispetto a quelli del container marittimo ed è predisposto per piu di tre lucchetti\n- Protezione della serratura al centro delle due porte\n- Ventilazione supplementare laterale\n- Noleggio possibile previo accordo\n- Garanzia del miglior prezzo per un container equivalente\n\nTRASPORTO E DEPOSITO\nPossiamo organizzare il trasporto del container scelto con camion gru o sideloader; per gli accessi piu difficili utilizziamo il RAM backloader. Dopo l’acquisto, il deposito presso il nostro terminale è gratuito fino a sei mesi. Un periodo piu lungo puo essere concordato se il sito non è ancora pronto o accessibile. Il prezzo del container resta invariato e il container scelto viene riservato per la data concordata.\n\nLe condizioni e i costi di consegna vengono definiti nel preventivo e confermati con il cliente prima della consegna.',
  `description_en` = COALESCE(NULLIF(`description_en`, ''), 'Sale of a new 40HC high-cube, 40-foot shipping container, reference MIIU3049105. Containers are manufactured in Asia and arrive at our terminal on a one-way shipment to avoid additional transport costs being added to the container price.\n\nFEATURES\n- 50-year weather-resistance guarantee\n- Photos correspond to the container presented; minor cosmetic marks from transport may be present\n- The shipping container has four locking points and can take more than three padlocks\n- The storage container has three locking points, raised compared with those on a shipping container, and can take more than three padlocks\n- Lock protection is centred between the two doors\n- Additional side ventilation\n- Rental available by arrangement\n- Best-price guarantee for an equivalent container\n\nTRANSPORT AND STORAGE\nWe can arrange transport for the selected container by crane truck or sideloader; a RAM backloader is used for difficult access. After purchase, storage at our terminal is free for up to six months. A longer period can be agreed if the site is not yet ready or accessible. The container price remains unchanged and the selected container is reserved for the agreed date.\n\nDelivery terms and costs are provided in a quotation and confirmed with the customer before delivery.'),
  `description_fr` = COALESCE(NULLIF(`description_fr`, ''), 'Vente d’un conteneur maritime neuf 40HC, high cube de 40 pieds, référence MIIU3049105. Les conteneurs sont fabriqués en Asie et arrivent à notre terminal par transport aller simple afin d’éviter l’ajout au prix du conteneur de frais de transport supplémentaires.\n\nCARACTÉRISTIQUES\n- Garantie de résistance aux intempéries de 50 ans\n- Les images correspondent au conteneur présenté ; de légers défauts esthétiques dus au transport peuvent être présents\n- Le conteneur maritime possède quatre points de fermeture et peut recevoir plus de trois cadenas\n- Le conteneur de stockage possède trois points de fermeture surélevés par rapport à ceux d’un conteneur maritime et peut recevoir plus de trois cadenas\n- Protection de serrure au centre des deux portes\n- Ventilation latérale supplémentaire\n- Location possible sur accord\n- Garantie du meilleur prix pour un conteneur équivalent\n\nTRANSPORT ET STOCKAGE\nNous pouvons organiser le transport du conteneur choisi par camion-grue ou sideloader ; le RAM backloader est utilisé pour les accès difficiles. Après l’achat, le stockage dans notre terminal est gratuit jusqu’à six mois. Une durée supérieure peut être convenue si le site n’est pas encore prêt ou accessible. Le prix du conteneur reste inchangé et le conteneur choisi est réservé pour la date convenue.\n\nLes modalités et les frais de livraison sont indiqués dans un devis et confirmés avec le client avant la livraison.'),
  `description_es` = COALESCE(NULLIF(`description_es`, ''), 'Venta de contenedor marítimo nuevo 40HC, high cube de 40 pies, referencia MIIU3049105. Los contenedores se fabrican en Asia y llegan a nuestra terminal mediante un transporte de solo ida, para evitar que se añadan al precio costes adicionales de transporte.\n\nCARACTERÍSTICAS\n- Garantía de resistencia a la intemperie de 50 años\n- Las imágenes corresponden al contenedor presentado; puede haber pequeños defectos estéticos causados por el transporte\n- El contenedor marítimo cuenta con cuatro puntos de cierre y admite más de tres candados\n- El contenedor de almacenamiento cuenta con tres puntos de cierre elevados respecto a los de un contenedor marítimo y admite más de tres candados\n- Protección de la cerradura en el centro de las dos puertas\n- Ventilación lateral adicional\n- Alquiler disponible previa consulta\n- Garantía del mejor precio para un contenedor equivalente\n\nTRANSPORTE Y ALMACENAMIENTO\nPodemos organizar el transporte del contenedor elegido con camión grúa o sideloader; para accesos difíciles utilizamos un RAM backloader. Después de la compra, el almacenamiento en nuestra terminal es gratuito hasta seis meses. Se puede acordar un plazo mayor si el lugar aún no está preparado o no es accesible. El precio del contenedor no cambia y el contenedor elegido queda reservado para la fecha acordada.\n\nLas condiciones y los costes de entrega se indican en un presupuesto y se confirman con el cliente antes de la entrega.'),
  `description_de` = COALESCE(NULLIF(`description_de`, ''), 'Verkauf eines neuen 40HC-High-Cube-Schiffscontainers mit 40 Fuss, Referenz MIIU3049105. Die Container werden in Asien hergestellt und im Einwegtransport zu unserem Terminal geliefert, um zusätzliche Transportkosten im Containerpreis zu vermeiden.\n\nMERKMALE\n- 50 Jahre Garantie auf Witterungsbeständigkeit\n- Die Bilder zeigen den angebotenen Container; leichte transportbedingte Gebrauchsspuren sind möglich\n- Der Schiffscontainer verfügt über vier Verriegelungspunkte und kann mit mehr als drei Vorhängeschlössern gesichert werden\n- Der Lagercontainer verfügt über drei gegenüber einem Schiffscontainer erhöhte Verriegelungspunkte und kann mit mehr als drei Vorhängeschlössern gesichert werden\n- Schlossabdeckung mittig zwischen den beiden Türen\n- Zusätzliche seitliche Belüftung\n- Miete nach Vereinbarung möglich\n- Bestpreisgarantie für einen gleichwertigen Container\n\nTRANSPORT UND LAGERUNG\nWir können den Transport des ausgewählten Containers mit Kran-Lkw oder Sideloader organisieren; bei schwieriger Zufahrt setzen wir einen RAM-Backloader ein. Nach dem Kauf ist die Lagerung an unserem Terminal bis zu sechs Monate kostenlos. Eine längere Dauer kann vereinbart werden, falls der Standort noch nicht vorbereitet oder zugänglich ist. Der Containerpreis bleibt unverändert und der ausgewählte Container wird für den vereinbarten Termin reserviert.\n\nLieferbedingungen und -kosten werden im Angebot festgelegt und vor der Lieferung mit dem Kunden bestätigt.'),
  `description_nl` = COALESCE(NULLIF(`description_nl`, ''), 'Verkoop van een nieuwe 40HC high-cube zeecontainer van 40 voet, referentie MIIU3049105. De containers worden in Azië geproduceerd en met een enkele reis naar onze terminal vervoerd om extra transportkosten in de containerprijs te vermijden.\n\nKENMERKEN\n- Garantie van 50 jaar op weerbestendigheid\n- De afbeeldingen tonen de aangeboden container; lichte cosmetische transportschade is mogelijk\n- De zeecontainer heeft vier sluitpunten en biedt ruimte voor meer dan drie hangsloten\n- De opslagcontainer heeft drie sluitpunten die hoger liggen dan bij een zeecontainer en biedt ruimte voor meer dan drie hangsloten\n- Slotbescherming in het midden van de twee deuren\n- Extra ventilatie aan de zijkanten\n- Verhuur mogelijk in overleg\n- Laagsteprijsgarantie voor een gelijkwaardige container\n\nVERVOER EN OPSLAG\nWe kunnen het vervoer van de gekozen container regelen met een kraanwagen of sideloader; voor moeilijke toegangen gebruiken we een RAM-backloader. Na aankoop is opslag op onze terminal tot zes maanden gratis. Een langere periode kan worden afgesproken als de locatie nog niet gereed of toegankelijk is. De containerprijs blijft gelijk en de gekozen container wordt voor de afgesproken datum gereserveerd.\n\nDe leveringsvoorwaarden en -kosten staan in een offerte en worden vóór levering met de klant bevestigd.'),
  `description_fi` = COALESCE(NULLIF(`description_fi`, ''), 'Uuden 40 jalan 40HC High Cube -merikontin myynti, viite MIIU3049105. Kontit valmistetaan Aasiassa ja toimitetaan terminaaliimme yhteen suuntaan, jotta kontin hintaan ei lisätä muita kuljetuskustannuksia.\n\nOMINAISUUDET\n- 50 vuoden säänkestävyystakuu\n- Kuvat vastaavat esiteltyä konttia; kuljetuksesta voi aiheutua vähäisiä kosmeettisia jälkiä\n- Merikontissa on neljä lukituskohtaa ja siihen voidaan asentaa yli kolme riippulukkoa\n- Varastokontissa on kolme merikontin lukituskohtia korkeammalla sijaitsevaa lukituskohtaa, ja siihen voidaan asentaa yli kolme riippulukkoa\n- Lukonsuoja kahden oven keskellä\n- Lisätuuletus sivuilla\n- Vuokraus mahdollista sopimuksen mukaan\n- Vastaavan kontin parhaan hinnan takuu\n\nKULJETUS JA VARASTOINTI\nVoimme järjestää valitun kontin kuljetuksen nosturiautolla tai sivulastaajalla; vaikeapääsyisiin kohteisiin käytämme RAM-backloaderia. Oston jälkeen varastointi terminaalissamme on maksutonta enintään kuusi kuukautta. Pidemmästä ajasta voidaan sopia, jos kohde ei ole vielä valmis tai saavutettavissa. Kontin hinta pysyy samana, ja valittu kontti varataan sovitulle päivälle.\n\nToimitusehdot ja -kulut ilmoitetaan tarjouksessa ja vahvistetaan asiakkaan kanssa ennen toimitusta.'),
  `description_ch` = COALESCE(NULLIF(`description_ch`, ''), 'Verkauf eines neuen 40HC-High-Cube-Schiffscontainers mit 40 Fuss, Referenz MIIU3049105. Die Container werden in Asien hergestellt und im Einwegtransport zu unserem Terminal geliefert, um zusätzliche Transportkosten im Containerpreis zu vermeiden.\n\nMERKMALE\n- 50 Jahre Garantie auf Witterungsbeständigkeit\n- Die Bilder zeigen den angebotenen Container; leichte transportbedingte Gebrauchsspuren sind möglich\n- Der Schiffscontainer verfügt über vier Verriegelungspunkte und kann mit mehr als drei Vorhängeschlössern gesichert werden\n- Der Lagercontainer verfügt über drei gegenüber einem Schiffscontainer erhöhte Verriegelungspunkte und kann mit mehr als drei Vorhängeschlössern gesichert werden\n- Schlossabdeckung mittig zwischen den beiden Türen\n- Zusätzliche seitliche Belüftung\n- Miete nach Vereinbarung möglich\n- Bestpreisgarantie für einen gleichwertigen Container\n\nTRANSPORT UND LAGERUNG\nWir können den Transport des ausgewählten Containers mit Kran-Lkw oder Sideloader organisieren; bei schwieriger Zufahrt setzen wir einen RAM-Backloader ein. Nach dem Kauf ist die Lagerung an unserem Terminal bis zu sechs Monate kostenlos. Eine längere Dauer kann vereinbart werden, falls der Standort noch nicht vorbereitet oder zugänglich ist. Der Containerpreis bleibt unverändert und der ausgewählte Container wird für den vereinbarten Termin reserviert.\n\nLieferbedingungen und -kosten werden im Angebot festgelegt und vor der Lieferung mit dem Kunden bestätigt.')
WHERE `id` = 34 AND `reference` = 'Conteneur maritime 40HC';

COMMIT;
